/* Tech Robòtica · unitat 3 «Sensor de distància» (ultrasons, «per sempre» i «si») */
Object.assign(TBADGE, {
  k_eco: { id: 'k_eco', ico: '🦇', n: "Oïda de ratpenat|Oído de murciélago", d: "Saps com mesura el sensor d'ultrasons: envia un so, escolta l'eco i ho converteix en centímetres.|Sabes cómo mide el sensor de ultrasonidos: envía un sonido, escucha el eco y lo convierte en centímetros." },
  k_fre: { id: 'k_fre', ico: '🧱', n: 'Frenada perfecta|Frenada perfecta', d: "Has programat el robot perquè s'aturi sol davant d'un mur, sigui on sigui, amb «per sempre» i «si… si no».|Has programado el robot para que se pare solo delante de un muro, esté donde esté, con «para siempre» y «si… si no»." },
  k_esquiva: { id: 'k_esquiva', ico: '🧭', n: 'Pilot/a esquivador/a|Piloto esquivador/a', d: "El teu robot detecta les caixes i les esquiva: gira, s'aparta i continua la ruta.|Tu robot detecta las cajas y las esquiva: gira, se aparta y sigue la ruta." },
  k_aparca: { id: 'k_aparca', ico: '🅿️', n: 'Aparcament automàtic|Aparcamiento automático', d: "Projecte acabat: el robot aparca sol, frena a poc a poc i s'atura a la distància justa a totes les pistes.|Proyecto terminado: el robot aparca solo, frena poco a poco y se para a la distancia justa en todas las pistas." }
});
ROBOTICA_UNITS[3] = { t: 'Sensor de distància|Sensor de distancia', d: 'Ultrasons, «per sempre» i «si»|Ultrasonidos, «para siempre» y «si»', color: '#2EA8F0', s: [
  /* ---------- Sessió 1 · Com mesura un robot? ---------- */
  { id: 'k3-1', t: 'Com mesura un robot?|¿Cómo mide un robot?', min: 45, badge: 'k_eco',
    learn: ["El sensor d'ultrasons envia un xiulet que no sentim, escolta l'eco i calcula la distància en centímetres.|El sensor de ultrasonidos envía un silbido que no oímos, escucha el eco y calcula la distancia en centímetros.",
      "Només veu el que té just al davant, de 2 a 400 cm; si no rep cap eco, el bloc distància dona 500.|Solo ve lo que tiene justo delante, de 2 a 400 cm; si no recibe ningún eco, el bloque distancia da 500.",
      "«En iniciar» fa els blocs una sola vegada; «per sempre» els repeteix sense parar, i així la mesura sempre està al dia.|«Al iniciar» hace los bloques una sola vez; «para siempre» los repite sin parar, y así la medida siempre está al día."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "Recordes la unitat anterior? A velocitat <b>150</b>, el Maqueen fa uns <b>15,6 cm cada segon</b>. Quant avança en <b>2 segons</b>?|¿Recuerdas la unidad anterior? A velocidad <b>150</b>, el Maqueen hace unos <b>15,6 cm cada segundo</b>. ¿Cuánto avanza en <b>2 segundos</b>?",
        opts: ['Uns 31 cm|Unos 31 cm', 'Uns 15 cm|Unos 15 cm', '150 cm|150 cm'], a: 0,
        ex: "Distància = velocitat × temps: 15,6 cm/s × 2 s ≈ 31 cm.|Distancia = velocidad × tiempo: 15,6 cm/s × 2 s ≈ 31 cm." },
      { k: 'quiz', ph: 'recorda', q: "Un programa amb temps fixos porta el robot just davant d'una caixa. Demà algú mou la caixa 20 cm més a prop. Què passarà?|Un programa con tiempos fijos lleva el robot justo delante de una caja. Mañana alguien mueve la caja 20 cm más cerca. ¿Qué pasará?",
        opts: ["El robot xocarà: fa el mateix camí que ahir, perquè no sap on és la caixa|El robot chocará: hace el mismo camino que ayer, porque no sabe dónde está la caja", "El robot s'aturarà abans, perquè veu la caixa|El robot se parará antes, porque ve la caja", "El robot anirà més a poc a poc|El robot irá más despacio"], a: 0,
        ex: "Amb només motors i temps, el robot va «a cegues». Per adaptar-se, necessita un <b>sensor</b>.|Con solo motores y tiempo, el robot va «a ciegas». Para adaptarse, necesita un <b>sensor</b>." },
      { k: 'story', ph: 'missio', who: 'numi', scene: 'moll', title: 'El magatzem del port|El almacén del puerto',
        t: "Benvinguts al <b>port de l'illa</b>! Cada nit arriben vaixells i les grues deixen caixes al magatzem del moll… però <b>mai al mateix lloc</b>. La capitana del port vol que el Maqueen porti paquets entre les caixes sense xocar. Problema: amb els programes de temps fix, el robot va a cegues.|¡Bienvenidos al <b>puerto de la isla</b>! Cada noche llegan barcos y las grúas dejan cajas en el almacén del muelle… pero <b>nunca en el mismo sitio</b>. La capitana del puerto quiere que el Maqueen lleve paquetes entre las cajas sin chocar. Problema: con los programas de tiempo fijo, el robot va a ciegas." },
      { k: 'story', ph: 'missio', who: 'numi', scene: 'moll', mood: 'happy', art: () => TANI.k3echo(),
        t: "Però el Maqueen té un truc al davant: aquests dos «ulls» platejats no són ulls, són un <b>altaveu i un micròfon d'ultrasons</b>. Funcionen com els <b>ratpenats</b>, que es mouen a les fosques fent xiulets i escoltant l'eco. Avui descobrirem com mesura un robot!|Pero el Maqueen tiene un truco delante: esos dos «ojos» plateados no son ojos, son un <b>altavoz y un micrófono de ultrasonidos</b>. Funcionan como los <b>murciélagos</b>, que se mueven a oscuras haciendo silbidos y escuchando el eco. ¡Hoy descubriremos cómo mide un robot!" },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'El problema|El problema', t: 'Un robot a cegues|Un robot a ciegas', robo: { w: { w: 120, h: 80, bot: [15, 40, 90], walls: [[70, 22, 10, 36]], time: 6 }, prog: 'start{ run:all,fwd,150 wait:4500 stop:all }' },
          x: "Aquest programa funcionava ahir, quan la caixa era més lluny: avançar 4,5 segons i parar. Avui la grua ha deixat la caixa més a prop i… <b>xoca</b>. El robot no sap on és la caixa: només compta el temps.|Este programa funcionaba ayer, cuando la caja estaba más lejos: avanzar 4,5 segundos y parar. Hoy la grúa ha dejado la caja más cerca y… <b>choca</b>. El robot no sabe dónde está la caja: solo cuenta el tiempo.",
          tip: "Un <b>sensor</b> és la part del robot que nota el món: llum, distància, colors, sons… Sense sensors, un robot no s'adapta a res.|Un <b>sensor</b> es la parte del robot que nota el mundo: luz, distancia, colores, sonidos… Sin sensores, un robot no se adapta a nada." },
        { k: "L'eco|El eco", t: 'Un xiulet que torna|Un silbido que vuelve', anim: 'k3echo',
          x: "El sensor d'ultrasons fa tres coses: <b>1)</b> un altaveu envia un xiulet molt agut (40.000 vibracions per segon, massa agut perquè el sentim); <b>2)</b> el so rebota a la caixa; <b>3)</b> el micròfon escolta l'<span class='hl'>eco</span>. Com més lluny és la caixa, més tarda a tornar l'eco.|El sensor de ultrasonidos hace tres cosas: <b>1)</b> un altavoz envía un silbido muy agudo (40.000 vibraciones por segundo, demasiado agudo para que lo oigamos); <b>2)</b> el sonido rebota en la caja; <b>3)</b> el micrófono escucha el <span class='hl'>eco</span>. Cuanto más lejos está la caja, más tarda en volver el eco.",
          tip: "Els ratpenats i els dofins fan el mateix per trobar el camí i el menjar: es diu <b>ecolocalització</b>.|Los murciélagos y los delfines hacen lo mismo para encontrar el camino y la comida: se llama <b>ecolocalización</b>." },
        { k: 'El càlcul|El cálculo', t: 'Del temps als centímetres|Del tiempo a los centímetros', anim: 'k3math',
          x: "El so viatja a uns <b>343 metres per segon</b>: uns <b>34 cm cada mil·lèsima de segon</b> (ms). Si l'eco torna al cap de 2 ms, el so ha fet 68 cm… però ha anat i tornat! Per tant, la caixa és a la meitat: <b>34 cm</b>.|El sonido viaja a unos <b>343 metros por segundo</b>: unos <b>34 cm cada milésima de segundo</b> (ms). Si el eco vuelve a los 2 ms, el sonido ha hecho 68 cm… ¡pero ha ido y vuelto! Por tanto, la caja está a la mitad: <b>34 cm</b>.",
          tip: "No has de fer aquest càlcul: la micro:bit el fa sola i et dona el resultat amb el bloc <b>distància (cm)</b>.|No tienes que hacer este cálculo: la micro:bit lo hace sola y te da el resultado con el bloque <b>distancia (cm)</b>." },
        { k: 'Què veu?|¿Qué ve?', t: 'Un con estret|Un cono estrecho', anim: 'k3cone',
          x: "El sensor només «veu» el que té <b>just al davant</b>, en un con estret. Mesura de <b>2 a 400 cm</b>. Si el so no troba res on rebotar (o se'n va lluny), l'eco no torna i el bloc distància dona <b>500</b>.|El sensor solo «ve» lo que tiene <b>justo delante</b>, en un cono estrecho. Mide de <b>2 a 400 cm</b>. Si el sonido no encuentra nada donde rebotar (o se va lejos), el eco no vuelve y el bloque distancia da <b>500</b>.",
          bad: "500 vol dir que hi ha una cosa a 500 cm.|500 quiere decir que hay algo a 500 cm.", good: "500 vol dir que no ha tornat cap eco: no veu res.|500 quiere decir que no ha vuelto ningún eco: no ve nada." },
        { k: 'Al simulador|En el simulador', t: 'La distància, en directe|La distancia, en directo', robo: { w: { w: 120, h: 80, bot: [15, 40, 90], walls: [[95, 22, 10, 36]], time: 6 }, prog: 'start{ run:all,fwd,100 } forever{ num:dist }' },
          x: "Fixa't en el con blau que surt del robot: és el so. La micro:bit mostra la <b>distància</b> fins a la caixa i el número va baixant mentre el robot s'acosta. Al tauler de sota l'arena també hi ha la distància, sempre al dia.|Fíjate en el cono azul que sale del robot: es el sonido. La micro:bit muestra la <b>distancia</b> hasta la caja y el número va bajando mientras el robot se acerca. En el tablero de debajo de la arena también está la distancia, siempre al día." }
      ] },
      { k: 'quiz', ph: 'mans', art: () => TANI.k3cone(), q: "El robot gira cap a la paret del fons, però està molt lluny i el so no hi arriba. Quin número dona el bloc <b>distància</b>?|El robot gira hacia la pared del fondo, pero está muy lejos y el sonido no llega. ¿Qué número da el bloque <b>distancia</b>?",
        opts: ['500|500', '0|0', '400|400'], a: 0,
        ex: "Quan no rep cap eco, la llibreria del Maqueen dona 500. Vol dir «no veig res», no «hi ha una cosa a 500 cm».|Cuando no recibe ningún eco, la librería del Maqueen da 500. Quiere decir «no veo nada», no «hay algo a 500 cm»." },
      { k: 'seq', ph: 'mans', q: "Ordena el que passa, pas a pas, cada vegada que el robot mesura una distància.|Ordena lo que pasa, paso a paso, cada vez que el robot mide una distancia.",
        items: ["L'altaveu envia un xiulet d'ultrasons|El altavoz envía un silbido de ultrasonidos", "El so viatja fins a la caixa|El sonido viaja hasta la caja", 'El so rebota i torna cap al robot|El sonido rebota y vuelve hacia el robot', "El micròfon escolta l'eco i es mesura el temps|El micrófono escucha el eco y se mide el tiempo", 'La micro:bit calcula la distància en cm|La micro:bit calcula la distancia en cm'],
        ex: "Tot això passa en menys d'una centèsima de segon!|¡Todo esto pasa en menos de una centésima de segundo!" },
      { k: 'unplug', ph: 'mans', ico: '⚽', title: "La pilota eco|La pelota eco",
        t: "Amb una pilota que boti i una paret llisa, pots entendre l'eco. La pilota fa de so!|Con una pelota que bote y una pared lisa, puedes entender el eco. ¡La pelota hace de sonido!",
        steps: ["Posa't a 2 passos d'una paret i fes rodolar la pilota cap a la paret, sempre amb la mateixa força.|Ponte a 2 pasos de una pared y haz rodar la pelota hacia la pared, siempre con la misma fuerza.",
          "Compta en veu alta («un, dos, tres…») fins que la pilota torna a la teva mà.|Cuenta en voz alta («uno, dos, tres…») hasta que la pelota vuelve a tu mano.",
          "Ara posa't a 4 passos i torna-ho a fer. Tarda més o menys a tornar?|Ahora ponte a 4 pasos y vuelve a hacerlo. ¿Tarda más o menos en volver?",
          "Conclusió: <b>com més lluny és la paret, més tarda a tornar</b>. El sensor d'ultrasons fa el mateix amb el so, però molt més de pressa.|Conclusión: <b>cuanto más lejos está la pared, más tarda en volver</b>. El sensor de ultrasonidos hace lo mismo con el sonido, pero mucho más deprisa."],
        tip: "Feu-ho en un passadís o al pati, lluny de coses que es puguin trencar.|Hacedlo en un pasillo o en el patio, lejos de cosas que se puedan romper." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Bloc nou|Bloque nuevo', t: 'Mostra el número|Muestra el número', robo: { w: { w: 120, h: 80, bot: [20, 40, 90], walls: [[70, 22, 10, 36]], time: 4 }, prog: 'start{ num:dist }' },
          x: "El bloc <b>mostra el número distància (cm)</b> demana una mesura al sensor i l'escriu a la pantalla de LEDs de la micro:bit. Aquí la caixa és a uns 46 cm. El bloc <b>distància</b> no és una ordre: és un <b>valor</b>, un número que va dins d'altres blocs.|El bloque <b>muestra el número distancia (cm)</b> pide una medida al sensor y la escribe en la pantalla de LEDs de la micro:bit. Aquí la caja está a unos 46 cm. El bloque <b>distancia</b> no es una orden: es un <b>valor</b>, un número que va dentro de otros bloques." },
        { k: 'Bucle nou|Bucle nuevo', t: '«En iniciar» o «per sempre»?|¿«Al iniciar» o «para siempre»?', anim: 'k3loop',
          x: "Els blocs d'<b>en iniciar</b> es fan <b>una sola vegada</b>, quan s'encén el robot: mesuren un cop i prou. Els blocs de <b>per sempre</b> es repeteixen <b>sense parar</b> mentre el robot està encès: tornen a mesurar una vegada i una altra, i el número sempre està al dia.|Los bloques de <b>al iniciar</b> se hacen <b>una sola vez</b>, cuando se enciende el robot: miden una vez y basta. Los bloques de <b>para siempre</b> se repiten <b>sin parar</b> mientras el robot está encendido: vuelven a medir una y otra vez, y el número siempre está al día.",
          tip: "Entre volta i volta, «per sempre» descansa 20 ms: són unes 50 voltes cada segon si a dins no hi ha esperes.|Entre vuelta y vuelta, «para siempre» descansa 20 ms: son unas 50 vueltas cada segundo si dentro no hay esperas." },
        { k: 'Compte!|¡Cuidado!', t: '«Per sempre» espera el seu torn|«Para siempre» espera su turno', robo: { w: { w: 120, h: 80, bot: [15, 40, 90], walls: [[95, 22, 10, 36]], time: 7 }, prog: 'start{ run:all,fwd,100 wait:4000 stop:all } forever{ num:dist }' },
          x: "Com a MakeCode, <b>«per sempre» no comença fins que «en iniciar» ha acabat</b>. Aquí «en iniciar» té una espera de 4 segons: mentre el robot avança, la pantalla no mostra res! Només quan s'atura, «per sempre» comença a mesurar.|Como en MakeCode, <b>«para siempre» no empieza hasta que «al iniciar» ha terminado</b>. Aquí «al iniciar» tiene una espera de 4 segundos: mientras el robot avanza, ¡la pantalla no muestra nada! Solo cuando se para, «para siempre» empieza a medir.",
          bad: "Poso esperes llargues a «en iniciar» i «per sempre» ja anirà fent.|Pongo esperas largas en «al iniciar» y «para siempre» ya irá haciendo.", good: "A «en iniciar», només el que cal fer al principi; el que s'ha de vigilar, a «per sempre».|En «al iniciar», solo lo que hay que hacer al principio; lo que hay que vigilar, en «para siempre»." },
        { k: 'Compte!|¡Cuidado!', t: 'Mostrar un número tarda|Mostrar un número tarda', anim: 'k3loop',
          x: "Un número de dues xifres <b>passa xifra a xifra per la pantalla</b> i tarda una estona: al simulador, gairebé un segon; a la micro:bit de veritat, encara més. Mentre el mostra, el programa no fa res més. Ho farem servir per comprovar mesures, però no per reaccionar de pressa.|Un número de dos cifras <b>pasa cifra a cifra por la pantalla</b> y tarda un rato: en el simulador, casi un segundo; en la micro:bit de verdad, todavía más. Mientras lo muestra, el programa no hace nada más. Lo usaremos para comprobar medidas, pero no para reaccionar deprisa." }
      ] },
      { k: 'rspot', ph: 'investiga', q: "Aquest programa fa avançar el robot a poc a poc. <b>Toca el bloc que fa servir el sensor d'ultrasons.</b>|Este programa hace avanzar el robot despacio. <b>Toca el bloque que usa el sensor de ultrasonidos.</b>",
        w: { w: 120, h: 80, bot: [15, 40, 90], walls: [[95, 22, 10, 36]], time: 6 }, prog: 'start{ run:all,fwd,100 } forever{ num:dist! }',
        yes: "Exacte! «Mostra el número distància» demana la mesura al sensor una vegada i una altra, dins de «per sempre».|¡Exacto! «Muestra el número distancia» pide la medida al sensor una y otra vez, dentro de «para siempre».",
        ex: "És «mostra el número distància (cm)»: el valor distància ve del sensor d'ultrasons. El motor no fa servir cap sensor.|Es «muestra el número distancia (cm)»: el valor distancia viene del sensor de ultrasonidos. El motor no usa ningún sensor." },
      { k: 'quiz', ph: 'investiga', art: () => TANI.k3loop(), q: "El robot avança cap a una caixa. Vols que la micro:bit mostri la distància <b>tota l'estona</b>, mentre s'acosta. On poses «mostra el número distància»?|El robot avanza hacia una caja. Quieres que la micro:bit muestre la distancia <b>todo el rato</b>, mientras se acerca. ¿Dónde pones «muestra el número distancia»?",
        opts: ["A «per sempre»|En «para siempre»", "A «en iniciar»|En «al iniciar»", 'En cap lloc: la micro:bit ja ho fa sola|En ningún sitio: la micro:bit ya lo hace sola'], a: 0,
        ex: "A «en iniciar» mesuraria una sola vegada. A «per sempre» torna a mesurar sense parar.|En «al iniciar» mediría una sola vez. En «para siempre» vuelve a medir sin parar." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Fes de sensor d'ultrasons! Estira el braç cap endavant com si fos el con del so i gira a poc a poc. Quan apuntis a una paret <b>a prop</b>, ajup-te; quan apuntis a una cosa <b>lluny</b>, posa't de puntetes; si apuntes a una finestra oberta… «500»: fes una estàtua!|¡Haz de sensor de ultrasonidos! Estira el brazo hacia delante como si fuera el cono del sonido y gira despacio. Cuando apuntes a una pared <b>cerca</b>, agáchate; cuando apuntes a algo <b>lejos</b>, ponte de puntillas; si apuntas a una ventana abierta… «500»: ¡haz una estatua!" },
      { k: 'robo', ph: 'repte', q: "Primer, <b>mesura</b>: mira al tauler a quina distància és la caixa. Després <b>calcula</b> quant ha d'avançar el robot per quedar-se a uns <b>10 cm</b> de la caixa (a velocitat 150 fa uns 15,6 cm cada segon). Si vols comprovar-ho, quan s'aturi pot <b>mostrar la distància</b>.|Primero, <b>mide</b>: mira en el tablero a qué distancia está la caja. Después <b>calcula</b> cuánto tiene que avanzar el robot para quedarse a unos <b>10 cm</b> de la caja (a velocidad 150 hace unos 15,6 cm cada segundo). Si quieres comprobarlo, cuando se pare puede <b>mostrar la distancia</b>.",
        w: { w: 120, h: 80, bot: [15, 40, 90], walls: [[85, 22, 10, 36]], goal: [{ k: 'near', min: 6, max: 14 }, { k: 'nohit' }] },
        pal: ['run', 'stop', 'wait', 'num'], ops: ['dist'], scripts: ['start'], sol: 'start{ run:all,fwd,150 wait:3600 stop:all num:dist }',
        hint: "La caixa és a 66 cm i vols quedar a 10 cm: ha d'avançar uns 56 cm. 56 ÷ 15,6 ≈ 3,6 segons, és a dir, 3600 ms. Després: atura.|La caja está a 66 cm y quieres quedarte a 10 cm: tiene que avanzar unos 56 cm. 56 ÷ 15,6 ≈ 3,6 segundos, es decir, 3600 ms. Después: para." },
      { k: 'robo', ph: 'repte', q: "El racó del magatzem: porta el robot fins al racó de dalt a la dreta. Ha d'avançar, <b>girar a l'esquerra</b> (90° en uns 590 ms a velocitat 100) i tornar a avançar fins a quedar-se a uns <b>10 cm</b> de la paret de dalt. Truc: fes primer la meitat del programa i mira al tauler quina distància mesura el robot després de girar.|El rincón del almacén: lleva el robot hasta el rincón de arriba a la derecha. Tiene que avanzar, <b>girar a la izquierda</b> (90° en unos 590 ms a velocidad 100) y volver a avanzar hasta quedarse a unos <b>10 cm</b> de la pared de arriba. Truco: haz primero la mitad del programa y mira en el tablero qué distancia mide el robot después de girar.",
        w: { w: 120, h: 80, bot: [15, 65, 90], walls: [[100, 8, 8, 72], [20, 8, 80, 6]], goal: [{ k: 'near', min: 6, max: 14 }, { k: 'nohit' }] },
        pal: ['run', 'stop', 'wait', 'num'], ops: ['dist'], scripts: ['start'], sol: 'start{ run:all,fwd,150 wait:4400 stop:all run:L,back,100 run:R,fwd,100 wait:590 run:all,fwd,150 wait:2500 stop:all }',
        hint: "Per girar a l'esquerra: motor esquerre enrere i motor dret endavant, tots dos a 100, i espera 590 ms. Si mostres la distància just després de girar, sabràs quant falta fins a la paret de dalt.|Para girar a la izquierda: motor izquierdo atrás y motor derecho adelante, los dos a 100, y espera 590 ms. Si muestras la distancia justo después de girar, sabrás cuánto falta hasta la pared de arriba." },
      { k: 'robo', ph: 'repte', q: "El vigilant del moll fa la ronda entre dues caixes <b>tota la nit</b>: avança, fa mitja volta, torna, fa mitja volta… Programa-ho amb <b>«per sempre»</b>. Només pots fer servir <b>5 blocs</b>, i ha de recórrer almenys 120 cm sense xocar.|El vigilante del muelle hace la ronda entre dos cajas <b>toda la noche</b>: avanza, da media vuelta, vuelve, da media vuelta… Prográmalo con <b>«para siempre»</b>. Solo puedes usar <b>5 bloques</b>, y tiene que recorrer al menos 120 cm sin chocar.",
        w: { w: 120, h: 80, bot: [30, 40, 90], walls: [[8, 20, 6, 40], [96, 20, 6, 40]], goal: [{ k: 'dist', min: 120 }, { k: 'nohit' }], time: 15 },
        pal: ['run', 'stop', 'wait'], ops: ['dist'], scripts: ['start', 'forever'], max: 5, sol: 'forever{ run:all,fwd,150 wait:2500 run:L,fwd,100 run:R,back,100 wait:1180 }',
        hint: "Dins de «per sempre»: avança uns 2,5 segons i fes mitja volta (un motor endavant i l'altre enrere a 100 durant 1180 ms, el doble que un gir de 90°). El bucle ja ho repetirà!|Dentro de «para siempre»: avanza unos 2,5 segundos y da media vuelta (un motor adelante y el otro atrás a 100 durante 1180 ms, el doble que un giro de 90°). ¡El bucle ya lo repetirá!" },
      { k: 'rcreate', ph: 'crea', name: 'El radar del far|El radar del faro', q: "Converteix el Maqueen en el <b>radar del far</b>: que giri a poc a poc sobre si mateix i que mostri la distància a cada direcció <b>per sempre</b>. Executa'l i observa: quan mira cap a una caixa, quin número surt? I quan mira cap a la paret del fons?|Convierte el Maqueen en el <b>radar del faro</b>: que gire despacio sobre sí mismo y que muestre la distancia en cada dirección <b>para siempre</b>. Ejecútalo y observa: cuando mira hacia una caja, ¿qué número sale? ¿Y cuando mira hacia la pared del fondo?",
        crit: ["Fa servir «per sempre»|Usa «para siempre»", "Mostra la distància amb «mostra el número»|Muestra la distancia con «muestra el número»", "El robot gira a trossos petits i no xoca|El robot gira a trozos pequeños y no choca"],
        w: { w: 120, h: 80, bot: [60, 40, 0], walls: [[52, 6, 16, 10], [100, 30, 10, 22], [20, 62, 14, 12], [8, 20, 8, 14]], goal: [{ k: 'nohit' }], time: 12 },
        pal: ['run', 'stop', 'wait', 'num'], ops: ['dist'], scripts: ['start', 'forever'], sol: 'forever{ num:dist run:L,fwd,100 run:R,back,100 wait:200 stop:all }',
        check: P => (P.forever || []).some(b => b.k === 'num') ? null : "Posa «mostra el número distància» dins de «per sempre», perquè torni a mesurar a cada gir.|Pon «muestra el número distancia» dentro de «para siempre», para que vuelva a medir en cada giro.",
        hint: "Dins de «per sempre»: mostra la distància, gira una mica (200 ms) i atura't. Cada volta mesura una direcció nova.|Dentro de «para siempre»: muestra la distancia, gira un poco (200 ms) y párate. Cada vuelta mide una dirección nueva." },
      { k: 'quiz', ph: 'tanca', q: "Per acabar: com sap el sensor d'ultrasons a quina distància és una caixa?|Para terminar: ¿cómo sabe el sensor de ultrasonidos a qué distancia está una caja?",
        opts: ["Mesura quant tarda a tornar l'eco d'un xiulet|Mide cuánto tarda en volver el eco de un silbido", 'Fa una foto i compta els píxels|Hace una foto y cuenta los píxeles', 'Toca la caixa amb una antena|Toca la caja con una antena'], a: 0 },
      { k: 'quiz', ph: 'tanca', q: "Quina diferència hi ha entre «en iniciar» i «per sempre»?|¿Qué diferencia hay entre «al iniciar» y «para siempre»?",
        opts: ["«En iniciar» fa els blocs un cop; «per sempre» els repeteix sense parar|«Al iniciar» hace los bloques una vez; «para siempre» los repite sin parar", "Cap: fan el mateix|Ninguna: hacen lo mismo", "«Per sempre» va més de pressa|«Para siempre» va más deprisa"], a: 0,
        ex: "Per vigilar un sensor tota l'estona, els blocs han d'anar a «per sempre».|Para vigilar un sensor todo el rato, los bloques tienen que ir en «para siempre»." },
      { k: 'feel', ph: 'tanca' }
    ] },

  /* ---------- Sessió 2 · Para abans del mur ---------- */
  { id: 'k3-2', t: 'Para abans del mur|Para antes del muro', min: 45, badge: 'k_fre',
    learn: ["El bloc «si… si no» fa una pregunta: si la resposta és sí, fa uns blocs; si és no, en fa uns altres.|El bloque «si… si no» hace una pregunta: si la respuesta es sí, hace unos bloques; si es no, hace otros.",
      "Dins de «per sempre», el robot torna a fer la pregunta moltes vegades cada segon, i per això s'atura a temps sigui on sigui el mur.|Dentro de «para siempre», el robot vuelve a hacer la pregunta muchas veces cada segundo, y por eso se para a tiempo esté donde esté el muro.",
      "El robot no frena en sec: com més de pressa va, abans ha de decidir aturar-se.|El robot no frena en seco: cuanto más deprisa va, antes tiene que decidir pararse."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "Recordes? Vols que el robot torni a mesurar la distància <b>sense parar</b>. On han d'anar els blocs?|¿Recuerdas? Quieres que el robot vuelva a medir la distancia <b>sin parar</b>. ¿Dónde tienen que ir los bloques?",
        opts: ["A «per sempre»|En «para siempre»", "A «en iniciar»|En «al iniciar»", 'Fora dels guions|Fuera de los guiones'], a: 0 },
      { k: 'quiz', ph: 'recorda', art: () => TANI.k3cone(), q: "El bloc distància dona <b>500</b>. Què vol dir?|El bloque distancia da <b>500</b>. ¿Qué quiere decir?",
        opts: ["Que no ha tornat cap eco: no veu res al davant|Que no ha vuelto ningún eco: no ve nada delante", 'Que hi ha una caixa a 5 metres|Que hay una caja a 5 metros', 'Que el sensor està espatllat|Que el sensor está estropeado'], a: 0 },
      { k: 'story', ph: 'missio', who: 'numi', scene: 'moll', title: 'Els contenidors ballarins|Los contenedores bailarines',
        t: "Al moll, el Maqueen ha d'anar fins a un <b>contenidor</b> i aturar-se a uns <b>10 cm</b>, perquè la grua hi pugui deixar el paquet. Però la grua deixa el contenidor <b>cada nit en un lloc diferent</b>. Un programa amb temps fixos no serveix. Necessitem un robot que <b>decideixi</b> quan s'ha d'aturar!|En el muelle, el Maqueen tiene que ir hasta un <b>contenedor</b> y pararse a unos <b>10 cm</b>, para que la grúa pueda dejar el paquete. Pero la grúa deja el contenedor <b>cada noche en un sitio diferente</b>. Un programa con tiempos fijos no sirve. ¡Necesitamos un robot que <b>decida</b> cuándo tiene que pararse!" },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Bloc nou|Bloque nuevo', t: '«Si… si no»: el robot decideix|«Si… si no»: el robot decide', anim: 'k3if',
          x: "El bloc <span class='hl'>si</span> fa una <b>pregunta</b> que només es pot respondre amb sí o no: «la distància és menor que 15?». <b>Si</b> la resposta és sí, fa els blocs de dins (atura). <b>Si no</b>, fa els de la part «si no» (endavant). Mai fa les dues coses alhora.|El bloque <span class='hl'>si</span> hace una <b>pregunta</b> que solo se puede responder con sí o no: «¿la distancia es menor que 15?». <b>Si</b> la respuesta es sí, hace los bloques de dentro (para). <b>Si no</b>, hace los de la parte «si no» (adelante). Nunca hace las dos cosas a la vez.",
          tip: "El signe <b>&lt;</b> vol dir «menor que» (15 &lt; 20) i el <b>&gt;</b>, «major que». La boca del signe s'obre cap al número més gran.|El signo <b>&lt;</b> quiere decir «menor que» (15 &lt; 20) y el <b>&gt;</b>, «mayor que». La boca del signo se abre hacia el número más grande." },
        { k: 'Al simulador|En el simulador', t: 'Para abans del mur|Para antes del muro', robo: { w: { w: 120, h: 80, bot: [15, 40, 90], walls: [[90, 15, 8, 50]], time: 7 }, prog: 'forever{ if:dist<15{ stop:all } else{ run:all,fwd,150 } }' },
          x: "Mira el programa: a cada volta de «per sempre», el robot pregunta si la distància és menor que 15. Mentre és lluny, la resposta és no i avança. Quan arriba a 15 cm, la resposta és sí i s'atura. <b>No hi ha cap espera</b>: decideix el sensor.|Mira el programa: en cada vuelta de «para siempre», el robot pregunta si la distancia es menor que 15. Mientras está lejos, la respuesta es no y avanza. Cuando llega a 15 cm, la respuesta es sí y se para. <b>No hay ninguna espera</b>: decide el sensor." },
        { k: 'Per què funciona?|¿Por qué funciona?', t: 'Pregunta, pregunta, pregunta…|Pregunta, pregunta, pregunta…', anim: 'k3if',
          x: "El «si» sol només pregunta <b>una vegada</b>. Dins de «per sempre», la pregunta es repeteix <b>moltes vegades cada segon</b> (al simulador, unes 50; al robot real, unes 20, perquè cada mesura tarda una mica): «ja hi soc? ja hi soc?», com quan feu un viatge llarg en cotxe. Per això el programa funciona amb el mur a qualsevol lloc.|El «si» solo pregunta <b>una vez</b>. Dentro de «para siempre», la pregunta se repite <b>muchas veces cada segundo</b> (en el simulador, unas 50; en el robot real, unas 20, porque cada medida tarda un poco): «¿ya estoy? ¿ya estoy?», como cuando hacéis un viaje largo en coche. Por eso el programa funciona con el muro en cualquier sitio.",
          bad: "Poso el «si» a «en iniciar».|Pongo el «si» en «al iniciar».", good: "Poso el «si» dins de «per sempre».|Pongo el «si» dentro de «para siempre»." },
        { k: 'La frenada|La frenada', t: 'El robot no frena en sec|El robot no frena en seco', anim: 'k3brake',
          x: "Quan el programa diu «atura», els motors paren, però el robot encara llisca una mica (tarda una dècima de segon a aturar-se, per la <b>inèrcia</b>). Com més de pressa va, més llisca. Per això, si va ràpid, li has de dir que s'aturi una mica <b>abans</b> (per exemple, a 12 cm en lloc de 8).|Cuando el programa dice «para», los motores se paran, pero el robot todavía se desliza un poco (tarda una décima de segundo en pararse, por la <b>inercia</b>). Cuanto más deprisa va, más se desliza. Por eso, si va rápido, le tienes que decir que se pare un poco <b>antes</b> (por ejemplo, a 12 cm en lugar de 8)." },
        { k: 'Compte!|¡Cuidado!', t: 'Un número que distreu|Un número que distrae', robo: { w: { w: 120, h: 80, bot: [15, 40, 90], walls: [[90, 15, 8, 50]], time: 6 }, prog: 'forever{ num:dist if:dist<15{ stop:all } else{ run:all,fwd,200 } }' },
          x: "Aquí hem posat «mostra el número» dins del bucle. Cada número tarda una estona a sortir (gairebé un segon, i al robot real encara més) i, mentre surt, el robot no torna a preguntar: quan se n'adona, ja és tard i <b>xoca</b>!|Aquí hemos puesto «muestra el número» dentro del bucle. Cada número tarda un rato en salir (casi un segundo, y en el robot real todavía más) y, mientras sale, el robot no vuelve a preguntar: cuando se da cuenta, ya es tarde y <b>¡choca!</b>",
          bad: "Mostro la distància a cada volta del bucle, per si de cas.|Muestro la distancia en cada vuelta del bucle, por si acaso.", good: "Al bucle, només el que el robot ha de vigilar. El número, quan ja està aturat.|En el bucle, solo lo que el robot tiene que vigilar. El número, cuando ya está parado." }
      ] },
      { k: 'rpredict', ph: 'prova', q: "El robot té aquest programa. <b>On s'aturarà?</b> Tria A, B o C i comprova-ho.|El robot tiene este programa. <b>¿Dónde se parará?</b> Elige A, B o C y compruébalo.",
        w: { w: 120, h: 80, bot: [15, 40, 90], walls: [[95, 15, 8, 50]], marks: { A: [40, 40], B: [72, 40], C: [90, 40] }, time: 8 }, prog: 'forever{ if:dist<20{ stop:all } else{ run:all,fwd,150 } }', a: 'B',
        ex: "S'atura quan la distància és menor que 20 cm: a B, una mica abans de la caixa.|Se para cuando la distancia es menor que 20 cm: en B, un poco antes de la caja." },
      { k: 'rpredict', ph: 'prova', q: "I ara? Fixa't bé: el «si» és a <b>«en iniciar»</b>. On acabarà el robot?|¿Y ahora? Fíjate bien: el «si» está en <b>«al iniciar»</b>. ¿Dónde terminará el robot?",
        w: { w: 120, h: 80, bot: [15, 40, 90], walls: [[95, 15, 8, 50]], marks: { A: [40, 40], B: [72, 40], C: [90, 40] }, time: 8 }, prog: 'start{ if:dist<20{ stop:all } else{ run:all,fwd,150 } }', a: 'C', scripts: ['start', 'forever'],
        ex: "A «en iniciar», el «si» pregunta una sola vegada, al principi: la caixa és lluny i diu «endavant». Ja no torna a preguntar mai més… i el robot xoca amb la caixa (C).|En «al iniciar», el «si» pregunta una sola vez, al principio: la caja está lejos y dice «adelante». Ya no vuelve a preguntar nunca más… y el robot choca con la caja (C)." },
      { k: 'unplug', ph: 'mans', ico: '🚦', title: 'El robot i el sensor humans|El robot y el sensor humanos',
        t: "Amb algú de casa: una persona fa de <b>robot</b> i l'altra, de <b>sensor</b>.|Con alguien de casa: una persona hace de <b>robot</b> y la otra, de <b>sensor</b>.",
        steps: ["El robot camina a poc a poc cap a una paret, amb petits passos.|El robot camina despacio hacia una pared, con pasos pequeños.",
          "A cada pas, el sensor diu en veu alta quants peus falten fins a la paret («sis peus», «cinc peus»…).|En cada paso, el sensor dice en voz alta cuántos pies faltan hasta la pared («seis pies», «cinco pies»…).",
          "El robot segueix la regla: <b>si falten menys de 3 peus, atura't; si no, fes un pas</b>.|El robot sigue la regla: <b>si faltan menos de 3 pies, párate; si no, da un paso</b>.",
          "Ara canvieu: comenceu més lluny o més a prop. La regla funciona igual? Per què?|Ahora cambiad: empezad más lejos o más cerca. ¿La regla funciona igual? ¿Por qué?"],
        tip: "Proveu també que el sensor «s'adormi» (que digui la distància només un cop cada 3 passos). Què passa?|Probad también que el sensor «se duerma» (que diga la distancia solo una vez cada 3 pasos). ¿Qué pasa?" },
      { k: 'rspot', ph: 'investiga', q: "<b>Toca el bloc que fa el robot quan la caixa és a prop.</b>|<b>Toca el bloque que hace el robot cuando la caja está cerca.</b>",
        w: { w: 120, h: 80, bot: [15, 40, 90], walls: [[90, 15, 8, 50]], time: 7 }, prog: 'forever{ if:dist<15{ stop:all! } else{ run:all,fwd,150 } }',
        yes: "Molt bé! Quan la distància és menor que 15 (resposta «sí»), fa els blocs de dins del «si»: atura.|¡Muy bien! Cuando la distancia es menor que 15 (respuesta «sí»), hace los bloques de dentro del «si»: para.",
        ex: "És «atura el motor», el que hi ha dins del «si». El «motor endavant» és a la part «si no»: es fa quan la caixa és lluny.|Es «para el motor», el que hay dentro del «si». El «motor adelante» está en la parte «si no»: se hace cuando la caja está lejos." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Semàfor de distància! Camina pel lloc. Algú diu números en veu alta: si el número és <b>menor que 10</b>, quedes quiet/a com una estàtua; si no, continues caminant. 5, 25, 8, 40, 3… Ets un robot amb «si… si no»!|¡Semáforo de distancia! Camina en el sitio. Alguien dice números en voz alta: si el número es <b>menor que 10</b>, te quedas quieto/a como una estatua; si no, sigues caminando. 5, 25, 8, 40, 3… ¡Eres un robot con «si… si no»!" },
      { k: 'robo', ph: 'repte', q: "El primer contenidor: fes que el robot avanci i <b>s'aturi sol</b> a uns 10 cm de la caixa (entre 5 i 14 cm), sense xocar. Fes servir «per sempre» i «si… si no».|El primer contenedor: haz que el robot avance y <b>se pare solo</b> a unos 10 cm de la caja (entre 5 y 14 cm), sin chocar. Usa «para siempre» y «si… si no».",
        w: { w: 120, h: 80, bot: [15, 40, 90], walls: [[90, 15, 8, 50]], goal: [{ k: 'near', min: 5, max: 14 }, { k: 'nohit' }] },
        pal: ['run', 'stop', 'if', 'else'], ops: ['dist'], scripts: ['start', 'forever'], sol: 'forever{ if:dist<12{ stop:all } else{ run:all,fwd,150 } }',
        hint: "Posa un «si» dins de «per sempre» i toca'l per afegir-hi «si no». Si la distància és menor que 12: atura. Si no: endavant a 150.|Pon un «si» dentro de «para siempre» y tócalo para añadirle «si no». Si la distancia es menor que 12: para. Si no: adelante a 150." },
      { k: 'robo', ph: 'repte', q: "La grua ha mogut el contenidor! El <b>mateix programa</b> ha de funcionar a les <b>3 pistes</b>: el contenidor és a prop, al mig o lluny. Quan una pista surti bé, el simulador provarà la següent.|¡La grúa ha movido el contenedor! El <b>mismo programa</b> tiene que funcionar en las <b>3 pistas</b>: el contenedor está cerca, en medio o lejos. Cuando una pista salga bien, el simulador probará la siguiente.",
        w: { w: 120, h: 80, bot: [15, 40, 90], walls: [[90, 15, 8, 50]], goal: [{ k: 'near', min: 5, max: 14 }, { k: 'nohit' }], alts: [{ walls: [[55, 15, 8, 50]] }, { walls: [[106, 10, 8, 60]] }] },
        pal: ['run', 'stop', 'wait', 'if', 'else'], ops: ['dist'], scripts: ['start', 'forever'], sol: 'forever{ if:dist<12{ stop:all } else{ run:all,fwd,150 } }',
        hint: "Si fas servir temps fixos (espera), només funcionarà a una pista. Deixa que decideixi el sensor: «per sempre» + «si distància < 12».|Si usas tiempos fijos (espera), solo funcionará en una pista. Deja que decida el sensor: «para siempre» + «si distancia < 12»." },
      { k: 'robo', ph: 'repte', q: "Ui! Aquest programa té un error i el robot <b>no es mou</b>. Troba'l i arregla'l perquè s'aturi a uns 10 cm del contenidor a les 3 pistes. Toca les parts del bloc «si» per canviar-les.|¡Uy! Este programa tiene un error y el robot <b>no se mueve</b>. Encuéntralo y arréglalo para que se pare a unos 10 cm del contenedor en las 3 pistas. Toca las partes del bloque «si» para cambiarlas.",
        w: { w: 120, h: 80, bot: [15, 40, 90], walls: [[90, 15, 8, 50]], goal: [{ k: 'near', min: 5, max: 14 }, { k: 'nohit' }], alts: [{ walls: [[55, 15, 8, 50]] }, { walls: [[106, 10, 8, 60]] }] },
        pal: ['run', 'stop', 'if', 'else'], ops: ['dist'], scripts: ['start', 'forever'], prog: 'forever{ if:dist>12{ stop:all } else{ run:all,fwd,150 } }', sol: 'forever{ if:dist<12{ stop:all } else{ run:all,fwd,150 } }',
        hint: "Llegeix la pregunta en veu alta: «si la distància és <b>major</b> que 12, atura't». Al principi la caixa és lluny… El signe ha de ser l'altre.|Lee la pregunta en voz alta: «si la distancia es <b>mayor</b> que 12, párate». Al principio la caja está lejos… El signo tiene que ser el otro." },
      { k: 'robo', ph: 'repte', q: "Ràpid però segur! Ha d'aparcar en <b>menys de 4 segons</b>, així que el robot ha d'anar a <b>255</b>. Però amb aquest programa s'acosta massa i gairebé toca el contenidor. Canvia la distància de la pregunta perquè s'aturi entre 6 i 14 cm a les 3 pistes.|¡Rápido pero seguro! Tiene que aparcar en <b>menos de 4 segundos</b>, así que el robot tiene que ir a <b>255</b>. Pero con este programa se acerca demasiado y casi toca el contenedor. Cambia la distancia de la pregunta para que se pare entre 6 y 14 cm en las 3 pistas.",
        w: { w: 120, h: 80, bot: [15, 40, 90], walls: [[90, 15, 8, 50]], goal: [{ k: 'near', min: 6, max: 14 }, { k: 'nohit' }, { k: 'time', max: 4 }], time: 6, alts: [{ walls: [[55, 15, 8, 50]] }, { walls: [[106, 10, 8, 60]] }] },
        pal: ['run', 'stop', 'if', 'else'], ops: ['dist'], scripts: ['start', 'forever'], prog: 'forever{ if:dist<5{ stop:all } else{ run:all,fwd,255 } }', sol: 'forever{ if:dist<12{ stop:all } else{ run:all,fwd,255 } }',
        hint: "A 255, el robot llisca uns quants centímetres després d'aturar els motors. Digues-li que s'aturi abans: per exemple, quan la distància sigui menor que 12. Si tarda més de 4 segons, és que va massa lent.|A 255, el robot se desliza unos cuantos centímetros después de parar los motores. Dile que se pare antes: por ejemplo, cuando la distancia sea menor que 12. Si tarda más de 4 segundos, es que va demasiado lento." },
      { k: 'rcreate', ph: 'crea', name: 'El robot del moll|El robot del muelle', q: "El teu robot del moll! Tria la velocitat i a quina distància s'atura (entre 5 i 18 cm del contenidor). Quan s'aturi, que <b>mostri la distància</b> a la micro:bit perquè la grua sàpiga que ja hi és. Ha de funcionar a les 3 pistes.|¡Tu robot del muelle! Elige la velocidad y a qué distancia se para (entre 5 y 18 cm del contenedor). Cuando se pare, que <b>muestre la distancia</b> en la micro:bit para que la grúa sepa que ya está. Tiene que funcionar en las 3 pistas.",
        crit: ["S'atura sol entre 5 i 18 cm, sense xocar, a les 3 pistes|Se para solo entre 5 y 18 cm, sin chocar, en las 3 pistas", "Fa servir «per sempre» i «si… si no»|Usa «para siempre» y «si… si no»", "Quan s'atura, mostra la distància|Cuando se para, muestra la distancia"],
        w: { w: 120, h: 80, bot: [15, 40, 90], walls: [[85, 18, 10, 44]], goal: [{ k: 'near', min: 5, max: 18 }, { k: 'nohit' }], alts: [{ walls: [[60, 18, 10, 44]] }, { walls: [[104, 12, 10, 56]] }] },
        pal: ['run', 'stop', 'wait', 'num', 'if', 'else'], ops: ['dist'], scripts: ['start', 'forever'], sol: 'forever{ if:dist<15{ stop:all num:dist } else{ run:all,fwd,180 } }',
        check: P => { const f = P.forever || [], ifs = f.filter(b => b.k === 'if'); if (!ifs.length) return "Posa un «si… si no» dins de «per sempre».|Pon un «si… si no» dentro de «para siempre»."; return ifs.some(b => [...(b.b || []), ...(b.e || [])].some(x => x.k === 'num')) ? null : "Falta que mostri la distància: posa «mostra el número» a la part del «si» on el robot s'atura.|Falta que muestre la distancia: pon «muestra el número» en la parte del «si» donde el robot se para."; },
        hint: "Dins del «si» (a prop): atura i mostra el número distància. A «si no» (lluny): endavant.|Dentro del «si» (cerca): para y muestra el número distancia. En «si no» (lejos): adelante." },
      { k: 'quiz', ph: 'tanca', q: "Per què el «si» ha d'anar dins de «per sempre» per aturar-se davant del mur?|¿Por qué el «si» tiene que ir dentro de «para siempre» para pararse delante del muro?",
        opts: ["Perquè així torna a preguntar la distància moltes vegades mentre avança|Porque así vuelve a preguntar la distancia muchas veces mientras avanza", "Perquè «per sempre» fa anar més de pressa els motors|Porque «para siempre» hace ir más deprisa los motores", 'Perquè el «si» no funciona a «en iniciar»|Porque el «si» no funciona en «al iniciar»'], a: 0 },
      { k: 'quiz', ph: 'tanca', art: () => TANI.k3brake(), q: "El robot ara va a 255 en lloc de 100. Què has de fer amb la distància a la qual s'atura?|El robot ahora va a 255 en lugar de 100. ¿Qué tienes que hacer con la distancia a la que se para?",
        opts: ["Fer-la una mica més gran, perquè llisca més abans d'aturar-se|Hacerla un poco más grande, porque se desliza más antes de pararse", 'Fer-la més petita|Hacerla más pequeña', 'Res: frena igual a totes les velocitats|Nada: frena igual a todas las velocidades'], a: 0 },
      { k: 'feel', ph: 'tanca' }
    ] },

  /* ---------- Sessió 3 · Esquiva obstacles ---------- */
  { id: 'k3-3', t: 'Esquiva obstacles|Esquiva obstáculos', min: 45, badge: 'k_esquiva',
    learn: ["Per esquivar, el «si» no atura el robot: el fa girar quan veu una caixa a prop i, si no n'hi ha, el fa avançar.|Para esquivar, el «si» no para el robot: lo hace girar cuando ve una caja cerca y, si no hay, lo hace avanzar.",
      "Dins del «si» hi pot haver una seqüència sencera: girar, apartar-se i tornar a girar.|Dentro del «si» puede haber una secuencia entera: girar, apartarse y volver a girar.",
      "Un bon programa amb sensors funciona a totes les pistes, encara que les caixes canviïn de lloc.|Un buen programa con sensores funciona en todas las pistas, aunque las cajas cambien de sitio."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "Recordes com gira el Maqueen <b>sobre si mateix cap a l'esquerra</b>?|¿Recuerdas cómo gira el Maqueen <b>sobre sí mismo hacia la izquierda</b>?",
        opts: ["Motor esquerre enrere i motor dret endavant|Motor izquierdo atrás y motor derecho adelante", 'Els dos motors enrere|Los dos motores atrás', "Motor esquerre endavant i motor dret enrere|Motor izquierdo adelante y motor derecho atrás"], a: 0,
        ex: "La roda dreta empeny endavant i l'esquerra tira enrere: el robot gira cap a l'esquerra. A velocitat 100, uns 590 ms fan un quart de volta (90°).|La rueda derecha empuja hacia delante y la izquierda tira hacia atrás: el robot gira hacia la izquierda. A velocidad 100, unos 590 ms hacen un cuarto de vuelta (90°)." },
      { k: 'quiz', ph: 'recorda', q: "Aquest programa: «per sempre: <b>si</b> distància &lt; 12, atura; <b>si no</b>, endavant». Què fa?|Este programa: «para siempre: <b>si</b> distancia &lt; 12, para; <b>si no</b>, adelante». ¿Qué hace?",
        opts: ["Avança i s'atura sol a uns 12 cm de l'obstacle, sigui on sigui|Avanza y se para solo a unos 12 cm del obstáculo, esté donde esté", "S'atura 12 segons|Se para 12 segundos", "Avança 12 cm i s'atura|Avanza 12 cm y se para"], a: 0 },
      { k: 'story', ph: 'missio', who: 'numi', scene: 'moll', title: 'El laberint de caixes|El laberinto de cajas',
        t: "Avui el magatzem del port està ple de caixes: han arribat tres vaixells alhora! La capitana necessita que el Maqueen porti un paquet <b>d'una punta a l'altra</b>. Si s'atura davant de cada caixa, no arribarà mai. Ha d'aprendre a <b>esquivar</b>: veure la caixa, girar i continuar.|Hoy el almacén del puerto está lleno de cajas: ¡han llegado tres barcos a la vez! La capitana necesita que el Maqueen lleve un paquete <b>de una punta a la otra</b>. Si se para delante de cada caja, no llegará nunca. Tiene que aprender a <b>esquivar</b>: ver la caja, girar y continuar." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'La idea|La idea', t: 'Si hi ha una caixa, gira|Si hay una caja, gira', robo: { w: { w: 120, h: 80, bot: [15, 62, 90], time: 14 }, prog: 'forever{ if:dist<15{ run:L,back,100 run:R,fwd,100 wait:590 } else{ run:all,fwd,150 } }' },
          x: "Canviem una sola cosa del programa d'aturar-se: quan la distància és menor que 15, en lloc d'aturar-se, el robot <b>gira 90° a l'esquerra</b>. Després el bucle torna a preguntar: si ja no hi ha res al davant, avança. Mira com recorre el magatzem resseguint les parets!|Cambiamos una sola cosa del programa de pararse: cuando la distancia es menor que 15, en lugar de pararse, el robot <b>gira 90° a la izquierda</b>. Después el bucle vuelve a preguntar: si ya no hay nada delante, avanza. ¡Mira cómo recorre el almacén siguiendo las paredes!" },
        { k: 'Una seqüència dins del «si»|Una secuencia dentro del «si»', t: 'Esquivar és girar, apartar-se i tornar|Esquivar es girar, apartarse y volver', anim: 'k3dodge',
          x: "Dins del «si» hi pots posar <b>molts blocs</b>, un darrere l'altre: gira a la dreta, avança una mica per apartar-te, gira a l'esquerra per tornar a mirar endavant. Quan acaba la seqüència, el bucle torna a preguntar. Així el robot passa pel costat de la caixa i continua.|Dentro del «si» puedes poner <b>muchos bloques</b>, uno detrás de otro: gira a la derecha, avanza un poco para apartarte, gira a la izquierda para volver a mirar adelante. Cuando termina la secuencia, el bucle vuelve a preguntar. Así el robot pasa por el lado de la caja y continúa." },
        { k: 'Al simulador|En el simulador', t: 'La maniobra completa|La maniobra completa', robo: { w: { w: 130, h: 80, bot: [12, 34, 90], walls: [[55, 28, 10, 12]], zones: [{ id: 'meta', r: [108, 4, 22, 72], col: 'green', label: 'META|META' }], time: 10 }, prog: 'forever{ if:dist<15{ run:L,fwd,100 run:R,back,100 wait:590 run:all,fwd,150 wait:1200 run:L,back,100 run:R,fwd,100 wait:590 } else{ run:all,fwd,150 } }' },
          x: "Aquí la seqüència del «si» té tres parts: <b>gir a la dreta</b> (590 ms), <b>endavant 1,2 segons</b> per apartar-se uns 19 cm, i <b>gir a l'esquerra</b> (590 ms). Després, el «si no» el fa continuar recte fins a la meta.|Aquí la secuencia del «si» tiene tres partes: <b>giro a la derecha</b> (590 ms), <b>adelante 1,2 segundos</b> para apartarse unos 19 cm, y <b>giro a la izquierda</b> (590 ms). Después, el «si no» lo hace seguir recto hasta la meta.",
          tip: "Mentre fa la seqüència del «si», el robot no mira el sensor: fes-la curta i segura.|Mientras hace la secuencia del «si», el robot no mira el sensor: hazla corta y segura." },
        { k: 'Compte!|¡Cuidado!', t: 'El con no veu els costats|El cono no ve los lados', anim: 'k3cone',
          x: "El sensor només mira <b>just al davant</b>. Una caixa que és una mica de costat pot quedar fora del con i el robot la pot tocar amb una cantonada. Solució: decideix girar una mica <b>abans</b> (15-20 cm) i aparta't prou per passar amb tot el cos (el Maqueen fa uns 8,5 cm d'amplada).|El sensor solo mira <b>justo delante</b>. Una caja que está un poco de lado puede quedar fuera del cono y el robot la puede tocar con una esquina. Solución: decide girar un poco <b>antes</b> (15-20 cm) y apártate lo suficiente para pasar con todo el cuerpo (el Maqueen mide unos 8,5 cm de ancho).",
          bad: "Si el sensor diu 500, segur que no hi ha res a prop.|Si el sensor dice 500, seguro que no hay nada cerca.", good: "500 vol dir que no hi ha res <b>al davant</b>; als costats hi pot haver coses.|500 quiere decir que no hay nada <b>delante</b>; a los lados puede haber cosas." }
      ] },
      { k: 'rpredict', ph: 'prova', q: "Aquest robot té la regla «si hi ha paret a menys de 15 cm, gira 90°» (mira quin motor va enrere!). Fins on haurà arribat al cap de 10 segons?|Este robot tiene la regla «si hay pared a menos de 15 cm, gira 90°» (¡mira qué motor va atrás!). ¿Hasta dónde habrá llegado al cabo de 10 segundos?",
        w: { w: 120, h: 80, bot: [15, 62, 90], time: 10, marks: { A: [104, 62], B: [101, 72], C: [101, 24] } }, prog: 'forever{ if:dist<15{ run:L,back,100 run:R,fwd,100 wait:590 } else{ run:all,fwd,150 } }', a: 'C',
        ex: "Arriba a la paret de la dreta, gira a l'esquerra (motor esquerre enrere) i continua cap amunt: a C. El «si» no l'atura, el fa girar.|Llega a la pared de la derecha, gira a la izquierda (motor izquierdo atrás) y sigue hacia arriba: a C. El «si» no lo para, lo hace girar." },
      { k: 'unplug', ph: 'mans', ico: '🧭', title: 'El laberint de coixins|El laberinto de cojines',
        t: "Construïu un passadís amb coixins, cadires o caixes. Una persona fa de robot amb els ulls tancats i les mans endavant com si fossin el sensor.|Construid un pasillo con cojines, sillas o cajas. Una persona hace de robot con los ojos cerrados y las manos adelante como si fueran el sensor.",
        steps: ["El robot camina a poc a poc amb els braços estirats endavant (el «con» del sensor).|El robot camina despacio con los brazos estirados hacia delante (el «cono» del sensor).",
          "Regla: <b>si les mans toquen alguna cosa, gira un quart de volta a l'esquerra; si no, fes un pas endavant</b>.|Regla: <b>si las manos tocan algo, gira un cuarto de vuelta a la izquierda; si no, da un paso adelante</b>.",
          "Algú vigila que el robot no es faci mal i compta quants girs fa fins a la sortida.|Alguien vigila que el robot no se haga daño y cuenta cuántos giros hace hasta la salida.",
          "Canvieu el passadís de lloc. La mateixa regla us porta a la sortida?|Cambiad el pasillo de sitio. ¿La misma regla os lleva a la salida?"],
        tip: "Aneu molt a poc a poc i sense obstacles durs a l'altura del cap. Qui vigila pot dir «stop!» en qualsevol moment.|Id muy despacio y sin obstáculos duros a la altura de la cabeza. Quien vigila puede decir «¡stop!» en cualquier momento." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Esquiva amb el cos! Camina pel lloc. Quan algú digui «caixa!», fes la maniobra: <b>un quart de volta a la dreta, dos passos, un quart de volta a l'esquerra</b>, i continua caminant. Ho pots fer cada cop més de pressa?|¡Esquiva con el cuerpo! Camina en el sitio. Cuando alguien diga «¡caja!», haz la maniobra: <b>un cuarto de vuelta a la derecha, dos pasos, un cuarto de vuelta a la izquierda</b>, y sigue caminando. ¿Puedes hacerlo cada vez más deprisa?" },
      { k: 'robo', ph: 'repte', q: "Fes que el robot avanci i, quan vegi la paret a prop, <b>giri a l'esquerra</b> i continuï fins a la <b>META</b>, sense xocar. Hi ha 3 magatzems d'amplades diferents: el mateix programa ha de funcionar als 3.|Haz que el robot avance y, cuando vea la pared cerca, <b>gire a la izquierda</b> y siga hasta la <b>META</b>, sin chocar. Hay 3 almacenes de anchos diferentes: el mismo programa tiene que funcionar en los 3.",
        w: { w: 120, h: 80, bot: [15, 62, 90], zones: [{ id: 'meta', r: [92, 0, 28, 26], col: 'green', label: 'META|META' }], goal: [{ k: 'zone', id: 'meta' }, { k: 'nohit' }], time: 20, alts: [{ w: 96, zones: [{ id: 'meta', r: [68, 0, 28, 26], col: 'green', label: 'META|META' }] }, { w: 140, zones: [{ id: 'meta', r: [112, 0, 28, 26], col: 'green', label: 'META|META' }] }] },
        pal: ['run', 'stop', 'wait', 'if', 'else'], ops: ['dist'], scripts: ['start', 'forever'], sol: 'forever{ if:dist<15{ run:L,back,100 run:R,fwd,100 wait:590 } else{ run:all,fwd,150 } }',
        hint: "Com el programa d'aturar-se, però dins del «si» posa el gir a l'esquerra: motor esquerre enrere a 100, motor dret endavant a 100 i espera 590 ms.|Como el programa de pararse, pero dentro del «si» pon el giro a la izquierda: motor izquierdo atrás a 100, motor derecho adelante a 100 y espera 590 ms." },
      { k: 'robo', ph: 'repte', q: "El passadís del magatzem fa dues corbes. Porta el paquet fins a la <b>META</b> sense xocar. Atenció: a cada pista el passadís és d'una llargada diferent!|El pasillo del almacén hace dos curvas. Lleva el paquete hasta la <b>META</b> sin chocar. Atención: ¡en cada pista el pasillo tiene una longitud diferente!",
        w: { w: 120, h: 80, bot: [15, 64, 90], walls: [[0, 44, 88, 5]], zones: [{ id: 'meta', r: [0, 0, 24, 44], col: 'green', label: 'META|META' }], goal: [{ k: 'zone', id: 'meta' }, { k: 'nohit' }], time: 30, alts: [{ w: 140, walls: [[0, 44, 106, 5]] }, { w: 100, h: 90, bot: [15, 72, 90], walls: [[0, 50, 68, 5]], zones: [{ id: 'meta', r: [0, 0, 24, 50], col: 'green', label: 'META|META' }] }] },
        pal: ['run', 'stop', 'wait', 'if', 'else'], ops: ['dist'], scripts: ['start', 'forever'], sol: 'forever{ if:dist<15{ run:L,back,100 run:R,fwd,100 wait:590 } else{ run:all,fwd,150 } }',
        hint: "Totes les corbes giren cap al mateix costat. Quin? Amb la mateixa regla del repte anterior n'hi ha prou.|Todas las curvas giran hacia el mismo lado. ¿Cuál? Con la misma regla del reto anterior basta." },
      { k: 'robo', ph: 'repte', q: "Ara la caixa és <b>al mig del camí</b>. Esquiva-la: quan la vegis a prop, gira a la dreta, aparta't i torna a mirar endavant. Arriba a la META sense xocar a les 3 pistes (a l'última n'hi ha dues!).|Ahora la caja está <b>en medio del camino</b>. Esquívala: cuando la veas cerca, gira a la derecha, apártate y vuelve a mirar adelante. Llega a la META sin chocar en las 3 pistas (¡en la última hay dos!).",
        w: { w: 130, h: 80, bot: [12, 34, 90], walls: [[55, 28, 10, 12]], zones: [{ id: 'meta', r: [108, 4, 22, 72], col: 'green', label: 'META|META' }], goal: [{ k: 'zone', id: 'meta' }, { k: 'nohit' }], time: 25, alts: [{ walls: [[32, 28, 10, 12]] }, { walls: [[40, 28, 10, 12], [85, 47, 10, 12]] }] },
        pal: ['run', 'stop', 'wait', 'if', 'else'], ops: ['dist'], scripts: ['start', 'forever'], sol: 'forever{ if:dist<15{ run:L,fwd,100 run:R,back,100 wait:590 run:all,fwd,150 wait:1200 run:L,back,100 run:R,fwd,100 wait:590 } else{ run:all,fwd,150 } }',
        hint: "Dins del «si»: gir a la dreta (esquerre endavant, dret enrere, 590 ms), endavant 1200 ms, gir a l'esquerra (esquerre enrere, dret endavant, 590 ms). A «si no»: endavant.|Dentro del «si»: giro a la derecha (izquierdo adelante, derecho atrás, 590 ms), adelante 1200 ms, giro a la izquierda (izquierdo atrás, derecho adelante, 590 ms). En «si no»: adelante." },
      { k: 'robo', ph: 'repte', q: "Aquest programa hauria de recórrer el passadís, però el robot <b>xoca</b>. Mira el «si no»: què hi fa aquella espera? Arregla'l perquè arribi a la META sense xocar.|Este programa debería recorrer el pasillo, pero el robot <b>choca</b>. Mira el «si no»: ¿qué hace ahí esa espera? Arréglalo para que llegue a la META sin chocar.",
        w: { w: 120, h: 80, bot: [15, 64, 90], walls: [[0, 44, 88, 5]], zones: [{ id: 'meta', r: [0, 0, 24, 44], col: 'green', label: 'META|META' }], goal: [{ k: 'zone', id: 'meta' }, { k: 'nohit' }], time: 30 },
        pal: ['run', 'stop', 'wait', 'if', 'else'], ops: ['dist'], scripts: ['start', 'forever'], prog: 'forever{ if:dist<15{ run:L,back,100 run:R,fwd,100 wait:590 } else{ run:all,fwd,150 wait:2000 } }', sol: 'forever{ if:dist<15{ run:L,back,100 run:R,fwd,100 wait:590 } else{ run:all,fwd,150 } }',
        hint: "Durant aquells 2 segons d'espera, el robot avança a cegues: no torna a preguntar la distància fins que acaba. Treu l'espera del «si no».|Durante esos 2 segundos de espera, el robot avanza a ciegas: no vuelve a preguntar la distancia hasta que termina. Quita la espera del «si no»." },
      { k: 'rcreate', ph: 'crea', name: "L'explorador del magatzem|El explorador del almacén", q: "Crea el teu <b>robot explorador</b>: ha de passejar pel magatzem ple de caixes durant 20 segons, recórrer almenys <b>160 cm</b> i <b>no xocar mai</b>. Tu tries cap a on gira, quant gira i a quina velocitat va. Prova diferents idees!|Crea tu <b>robot explorador</b>: tiene que pasear por el almacén lleno de cajas durante 20 segundos, recorrer al menos <b>160 cm</b> y <b>no chocar nunca</b>. Tú eliges hacia dónde gira, cuánto gira y a qué velocidad va. ¡Prueba diferentes ideas!",
        crit: ["Fa servir «per sempre» i «si… si no» amb la distància|Usa «para siempre» y «si… si no» con la distancia", 'Recorre almenys 160 cm|Recorre al menos 160 cm', 'No xoca mai amb cap caixa ni paret|No choca nunca con ninguna caja ni pared'],
        w: { w: 140, h: 90, bot: [20, 45, 90], walls: [[60, 30, 14, 14], [100, 58, 14, 14], [40, 70, 12, 12], [95, 10, 12, 12]], goal: [{ k: 'dist', min: 160 }, { k: 'nohit' }], time: 20 },
        pal: ['run', 'stop', 'wait', 'if', 'else'], ops: ['dist'], scripts: ['start', 'forever'], sol: 'forever{ if:dist<20{ run:L,fwd,100 run:R,back,100 wait:590 } else{ run:all,fwd,150 } }',
        check: P => (P.forever || []).some(b => b.k === 'if') ? null : "Posa un «si… si no» dins de «per sempre» perquè el robot decideixi quan ha de girar.|Pon un «si… si no» dentro de «para siempre» para que el robot decida cuándo tiene que girar.",
        hint: "Comença amb la regla del passadís i decideix girar una mica abans (per exemple, a 20 cm), perquè les caixes del mig no es toquin amb les cantonades.|Empieza con la regla del pasillo y decide girar un poco antes (por ejemplo, a 20 cm), para que las cajas del medio no se toquen con las esquinas." },
      { k: 'quiz', ph: 'tanca', q: "Quina és la diferència entre el programa d'<b>aturar-se</b> i el d'<b>esquivar</b>?|¿Cuál es la diferencia entre el programa de <b>pararse</b> y el de <b>esquivar</b>?",
        opts: ["El que hi ha dins del «si»: atura o fa una maniobra de gir|Lo que hay dentro del «si»: para o hace una maniobra de giro", 'Esquivar no fa servir el sensor|Esquivar no usa el sensor', "Aturar-se no necessita «per sempre»|Pararse no necesita «para siempre»"], a: 0 },
      { k: 'quiz', ph: 'tanca', q: "Per què posar una espera llarga al «si no» pot fer xocar el robot?|¿Por qué poner una espera larga en el «si no» puede hacer chocar el robot?",
        opts: ["Perquè mentre espera no torna a mirar el sensor|Porque mientras espera no vuelve a mirar el sensor", "Perquè les esperes fan anar més ràpid el robot|Porque las esperas hacen ir más rápido el robot", "Perquè el sensor s'apaga|Porque el sensor se apaga"], a: 0 },
      { k: 'feel', ph: 'tanca' }
    ] },

  /* ---------- Sessió 4 · Projecte: aparcament automàtic ---------- */
  { id: 'k3-4', t: 'Projecte: aparcament automàtic|Proyecto: aparcamiento automático', min: 45, proj: true, badge: 'k_aparca',
    learn: ["Un «si» dins d'un altre «si» permet tres comportaments: lluny, a prop i molt a prop.|Un «si» dentro de otro «si» permite tres comportamientos: lejos, cerca y muy cerca.",
      "L'ordre de les preguntes importa: primer cal preguntar pel cas més urgent (molt a prop).|El orden de las preguntas importa: primero hay que preguntar por el caso más urgente (muy cerca).",
      "Els enginyers planifiquen, programen, proven a moltes pistes i milloren, i el programa es pot passar al robot de veritat.|Los ingenieros planifican, programan, prueban en muchas pistas y mejoran, y el programa se puede pasar al robot de verdad."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "Per esquivar una caixa, què posem dins del «si»?|Para esquivar una caja, ¿qué ponemos dentro del «si»?",
        opts: ["Una maniobra: girar, apartar-se i tornar a girar|Una maniobra: girar, apartarse y volver a girar", 'Una espera molt llarga|Una espera muy larga', 'Res: el robot ja esquiva sol|Nada: el robot ya esquiva solo'], a: 0 },
      { k: 'story', ph: 'missio', who: 'numi', scene: 'moll', title: "L'aparcament del port|El aparcamiento del puerto",
        t: "La capitana del port té una idea: un <b>aparcament automàtic</b> per als carretons elèctrics del moll. Cada carretó ha d'entrar a la seva plaça, <b>frenar a poc a poc</b> quan s'acosta a la paret i aturar-se a la distància justa, ni massa lluny ni tocant. I les places no tenen totes la mateixa llargada! Aquest és el vostre projecte d'enginyeria.|La capitana del puerto tiene una idea: un <b>aparcamiento automático</b> para las carretillas eléctricas del muelle. Cada carretilla tiene que entrar en su plaza, <b>frenar poco a poco</b> cuando se acerca a la pared y pararse a la distancia justa, ni demasiado lejos ni tocando. ¡Y las plazas no tienen todas la misma longitud! Este es vuestro proyecto de ingeniería." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'A la vida real|En la vida real', t: "El sensor d'aparcament|El sensor de aparcamiento", anim: 'k3park',
          x: "Molts cotxes porten <b>sensors d'ultrasons al para-xocs</b>, com el del Maqueen. Quan aparques, fan «bip… bip…» i, com més a prop de la paret, més ràpid sonen. El nostre robot farà el mateix amb la velocitat: <b>lluny</b>, ràpid; <b>a prop</b>, a poc a poc; <b>molt a prop</b>, s'atura.|Muchos coches llevan <b>sensores de ultrasonidos en el parachoques</b>, como el del Maqueen. Cuando aparcas, hacen «bip… bip…» y, cuanto más cerca de la pared, más rápido suenan. Nuestro robot hará lo mismo con la velocidad: <b>lejos</b>, rápido; <b>cerca</b>, despacio; <b>muy cerca</b>, se para." },
        { k: 'Tres casos|Tres casos', t: 'Un «si» dins d\'un altre «si»|Un «si» dentro de otro «si»', robo: { w: { w: 120, h: 80, bot: [12, 40, 90], walls: [[95, 26, 6, 28], [62, 24, 39, 3], [62, 53, 39, 3]], zones: [{ id: 'p', r: [66, 27, 29, 26], col: 'blue', label: 'P|P' }], time: 9 }, prog: 'forever{ if:dist<8{ stop:all } else{ if:dist<30{ run:all,fwd,70 } else{ run:all,fwd,200 } } }' },
          x: "Amb un sol «si» només hi ha dos camins. Per tenir-ne tres, posem un altre «si» a la part «si no»: <b>si</b> distància &lt; 8 → atura; <b>si no, si</b> distància &lt; 30 → a poc a poc (70); <b>si no</b> → ràpid (200). Mira com frena en entrar a la plaça.|Con un solo «si» solo hay dos caminos. Para tener tres, ponemos otro «si» en la parte «si no»: <b>si</b> distancia &lt; 8 → para; <b>si no, si</b> distancia &lt; 30 → despacio (70); <b>si no</b> → rápido (200). Mira cómo frena al entrar en la plaza." },
        { k: 'Compte!|¡Cuidado!', t: "L'ordre de les preguntes|El orden de las preguntas", anim: 'k3park',
          x: "El robot fa les preguntes <b>de dalt a baix</b> i es queda amb la primera que diu sí. Si primer preguntes «distància &lt; 30?», quan sigui a 5 cm també dirà sí (5 és menor que 30!) i mai arribarà a la pregunta d'aturar-se. Primer, el cas més urgent: <b>molt a prop</b>.|El robot hace las preguntas <b>de arriba abajo</b> y se queda con la primera que dice sí. Si primero preguntas «¿distancia &lt; 30?», cuando esté a 5 cm también dirá sí (¡5 es menor que 30!) y nunca llegará a la pregunta de pararse. Primero, el caso más urgente: <b>muy cerca</b>.",
          bad: "si dist. &lt; 30 → a poc a poc; si no, si dist. &lt; 8 → atura|si dist. &lt; 30 → despacio; si no, si dist. &lt; 8 → para", good: "si dist. &lt; 8 → atura; si no, si dist. &lt; 30 → a poc a poc|si dist. &lt; 8 → para; si no, si dist. &lt; 30 → despacio" },
        { k: 'Com els enginyers|Como los ingenieros', t: 'Planifica, programa, prova, millora|Planifica, programa, prueba, mejora', anim: 'k3brake',
          x: "Un projecte no surt bé a la primera. Els enginyers fan un <b>pla</b> (què ha de fer el robot a cada cas), el <b>programen</b>, el <b>proven</b> a moltes pistes diferents i el <b>milloren</b> a poc a poc: una mica més de velocitat, una mica abans de frenar…|Un proyecto no sale bien a la primera. Los ingenieros hacen un <b>plan</b> (qué tiene que hacer el robot en cada caso), lo <b>programan</b>, lo <b>prueban</b> en muchas pistas diferentes y lo <b>mejoran</b> poco a poco: un poco más de velocidad, un poco antes de frenar…" }
      ] },
      { k: 'seq', ph: 'mans', q: "Ordena el pla del carretó, de quan entra a la plaça fins que aparca.|Ordena el plan de la carretilla, desde que entra en la plaza hasta que aparca.",
        items: ['Lluny de la paret: endavant ràpid (200)|Lejos de la pared: adelante rápido (200)', 'A menys de 30 cm: frena i va a poc a poc (70)|A menos de 30 cm: frena y va despacio (70)', "A menys de 8 cm: s'atura del tot|A menos de 8 cm: se para del todo", 'Aparcat: mostra la distància a la micro:bit|Aparcado: muestra la distancia en la micro:bit'],
        ex: "Aquest és l'algorisme del projecte. Ara cal traduir-lo a blocs: cada cas és una part del «si».|Este es el algoritmo del proyecto. Ahora hay que traducirlo a bloques: cada caso es una parte del «si»." },
      { k: 'unplug', ph: 'mans', ico: '📝', title: 'El pla en paper|El plan en papel',
        t: "Abans de programar, dibuixa el pla. Agafa un full i un llapis.|Antes de programar, dibuja el plan. Coge una hoja y un lápiz.",
        steps: ["Dibuixa la plaça d'aparcament vista des de dalt, amb la paret del fons.|Dibuja la plaza de aparcamiento vista desde arriba, con la pared del fondo.",
          "Pinta tres franges: verda (lluny), groga (a prop, menys de 30 cm) i vermella (molt a prop, menys de 8 cm).|Pinta tres franjas: verde (lejos), amarilla (cerca, menos de 30 cm) y roja (muy cerca, menos de 8 cm).",
          "Al costat de cada franja, escriu què ha de fer el robot i a quina velocitat.|Al lado de cada franja, escribe qué tiene que hacer el robot y a qué velocidad.",
          "Escriu el programa amb paraules: «per sempre: si… si no, si… si no…». Després el copiaràs amb blocs.|Escribe el programa con palabras: «para siempre: si… si no, si… si no…». Después lo copiarás con bloques."],
        tip: "Ensenya el pla a algú i explica-li-ho: si ho entén, el pla és clar!|Enseña el plan a alguien y explícaselo: si lo entiende, ¡el plan está claro!" },
      { k: 'robo', ph: 'repte', q: "Primera prova: el carretó entra a la plaça i <b>s'atura entre 4 i 10 cm</b> de la paret del fons, dins de la plaça i sense tocar res. Les 3 places tenen llargades diferents.|Primera prueba: la carretilla entra en la plaza y <b>se para entre 4 y 10 cm</b> de la pared del fondo, dentro de la plaza y sin tocar nada. Las 3 plazas tienen longitudes diferentes.",
        w: { w: 120, h: 80, bot: [12, 40, 90], walls: [[95, 26, 6, 28], [62, 24, 39, 3], [62, 53, 39, 3]], zones: [{ id: 'p', r: [66, 27, 29, 26], col: 'blue', label: 'P|P' }], goal: [{ k: 'zone', id: 'p', stop: true }, { k: 'near', min: 4, max: 10 }, { k: 'nohit' }], alts: [{ walls: [[80, 26, 6, 28], [47, 24, 39, 3], [47, 53, 39, 3]], zones: [{ id: 'p', r: [51, 27, 29, 26], col: 'blue', label: 'P|P' }] }, { walls: [[110, 26, 6, 28], [77, 24, 39, 3], [77, 53, 39, 3]], zones: [{ id: 'p', r: [81, 27, 29, 26], col: 'blue', label: 'P|P' }] }] },
        pal: ['run', 'stop', 'if', 'else'], ops: ['dist'], scripts: ['start', 'forever'], sol: 'forever{ if:dist<8{ stop:all } else{ run:all,fwd,150 } }',
        hint: "Amb un sol «si… si no» n'hi ha prou: si la distància és menor que 8, atura; si no, endavant a 150.|Con un solo «si… si no» basta: si la distancia es menor que 8, para; si no, adelante a 150." },
      { k: 'rpredict', ph: 'prova', q: "Aquest programa té les preguntes <b>en un altre ordre</b>. On acabarà el carretó?|Este programa tiene las preguntas <b>en otro orden</b>. ¿Dónde terminará la carretilla?",
        w: { w: 120, h: 80, bot: [12, 40, 90], walls: [[95, 26, 6, 28], [62, 24, 39, 3], [62, 53, 39, 3]], zones: [{ id: 'p', r: [66, 27, 29, 26], col: 'blue', label: 'P|P' }], marks: { A: [50, 40], B: [84, 40], C: [90, 40] }, time: 12 }, prog: 'forever{ if:dist<30{ run:all,fwd,70 } else{ if:dist<8{ stop:all } else{ run:all,fwd,200 } } }', a: 'C',
        ex: "Quan és a menys de 30 cm, la primera pregunta ja diu sí i va a poc a poc… però mai arriba a la pregunta «menys de 8?», i acaba tocant la paret (C).|Cuando está a menos de 30 cm, la primera pregunta ya dice sí y va despacio… pero nunca llega a la pregunta «¿menos de 8?», y acaba tocando la pared (C)." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Aparcament humà! Camina cap a una paret: lluny, passes llargues i ràpides; quan siguis a tres passos, passes petites i lentes; quan siguis a un pas, atura't i aixeca els braços: «aparcat!». Torna enrere i repeteix-ho dues vegades.|¡Aparcamiento humano! Camina hacia una pared: lejos, pasos largos y rápidos; cuando estés a tres pasos, pasos pequeños y lentos; cuando estés a un paso, párate y levanta los brazos: «¡aparcado!». Vuelve atrás y repítelo dos veces." },
      { k: 'robo', ph: 'repte', q: "Aquest programa de tres casos té les preguntes <b>en mal ordre</b> i el carretó toca la paret. Arregla'l perquè <b>freni a poc a poc i s'aturi</b> entre 3 i 10 cm, a les 3 places.|Este programa de tres casos tiene las preguntas <b>en mal orden</b> y la carretilla toca la pared. Arréglalo para que <b>frene poco a poco y se pare</b> entre 3 y 10 cm, en las 3 plazas.",
        w: { w: 120, h: 80, bot: [12, 40, 90], walls: [[95, 26, 6, 28], [62, 24, 39, 3], [62, 53, 39, 3]], zones: [{ id: 'p', r: [66, 27, 29, 26], col: 'blue', label: 'P|P' }], goal: [{ k: 'zone', id: 'p', stop: true }, { k: 'near', min: 3, max: 10 }, { k: 'nohit' }], alts: [{ walls: [[80, 26, 6, 28], [47, 24, 39, 3], [47, 53, 39, 3]], zones: [{ id: 'p', r: [51, 27, 29, 26], col: 'blue', label: 'P|P' }] }, { walls: [[110, 26, 6, 28], [77, 24, 39, 3], [77, 53, 39, 3]], zones: [{ id: 'p', r: [81, 27, 29, 26], col: 'blue', label: 'P|P' }] }] },
        pal: ['run', 'stop', 'if', 'else'], ops: ['dist'], scripts: ['start', 'forever'], prog: 'forever{ if:dist<30{ run:all,fwd,70 } else{ if:dist<8{ stop:all } else{ run:all,fwd,200 } } }', sol: 'forever{ if:dist<8{ stop:all } else{ if:dist<30{ run:all,fwd,70 } else{ run:all,fwd,200 } } }',
        hint: "La primera pregunta ha de ser la més urgent: «distància &lt; 8?». Canvia els números de les dues preguntes: el 8 a dalt i el 30 a sota (i també el que fa cada una).|La primera pregunta tiene que ser la más urgente: «¿distancia &lt; 8?». Cambia los números de las dos preguntas: el 8 arriba y el 30 abajo (y también lo que hace cada una)." },
      { k: 'robo', ph: 'repte', q: "La zona de seguretat: el carretó ha de quedar <b>entre 9 i 17 cm</b> del contenidor. Però de vegades algú l'ha deixat <b>massa a prop</b>! Si és a menys de 10 cm, que vagi <b>enrere</b>; si és a més de 16, endavant; i si no, quiet. Ha de funcionar a les 3 pistes.|La zona de seguridad: la carretilla tiene que quedar <b>entre 9 y 17 cm</b> del contenedor. ¡Pero a veces alguien la ha dejado <b>demasiado cerca</b>! Si está a menos de 10 cm, que vaya <b>atrás</b>; si está a más de 16, adelante; y si no, quieta. Tiene que funcionar en las 3 pistas.",
        w: { w: 120, h: 80, bot: [40, 40, 90], walls: [[90, 20, 8, 40]], goal: [{ k: 'near', min: 9, max: 17 }, { k: 'nohit' }], time: 12, alts: [{ bot: [82, 40, 90] }, { bot: [15, 40, 90] }] },
        pal: ['run', 'stop', 'if', 'else'], ops: ['dist'], scripts: ['start', 'forever'], sol: 'forever{ if:dist<10{ run:all,back,100 } else{ if:dist>16{ run:all,fwd,100 } else{ stop:all } } }',
        hint: "Tres casos: si distància &lt; 10 → motors enrere a 100; si no, si distància &gt; 16 → endavant a 100; si no → atura. A la pista 2 el carretó comença gairebé tocant!|Tres casos: si distancia &lt; 10 → motores atrás a 100; si no, si distancia &gt; 16 → adelante a 100; si no → para. ¡En la pista 2 la carretilla empieza casi tocando!" },
      { k: 'rcreate', ph: 'crea', name: 'El meu aparcament automàtic|Mi aparcamiento automático', q: "<b>El teu projecte!</b> Programa l'aparcament automàtic amb el teu pla: el carretó ha d'anar ràpid quan és lluny, <b>frenar a poc a poc</b> en acostar-se i aturar-se entre 3 i 10 cm de la paret, dins de la plaça, a les 3 places. Tria tu les velocitats i les distàncies. Quan aparqui, pot mostrar la distància.|<b>¡Tu proyecto!</b> Programa el aparcamiento automático con tu plan: la carretilla tiene que ir rápido cuando está lejos, <b>frenar poco a poco</b> al acercarse y pararse entre 3 y 10 cm de la pared, dentro de la plaza, en las 3 plazas. Elige tú las velocidades y las distancias. Cuando aparque, puede mostrar la distancia.",
        crit: ['Té tres casos: lluny, a prop i molt a prop (un «si» dins d\'un altre)|Tiene tres casos: lejos, cerca y muy cerca (un «si» dentro de otro)', "S'atura entre 3 i 10 cm de la paret, dins de la plaça, sense tocar res|Se para entre 3 y 10 cm de la pared, dentro de la plaza, sin tocar nada", 'Funciona a les 3 places|Funciona en las 3 plazas'],
        w: { w: 120, h: 80, bot: [12, 40, 90], walls: [[95, 26, 6, 28], [62, 24, 39, 3], [62, 53, 39, 3]], zones: [{ id: 'p', r: [66, 27, 29, 26], col: 'blue', label: 'P|P' }], goal: [{ k: 'zone', id: 'p', stop: true }, { k: 'near', min: 3, max: 10 }, { k: 'nohit' }], alts: [{ walls: [[80, 26, 6, 28], [47, 24, 39, 3], [47, 53, 39, 3]], zones: [{ id: 'p', r: [51, 27, 29, 26], col: 'blue', label: 'P|P' }] }, { walls: [[110, 26, 6, 28], [77, 24, 39, 3], [77, 53, 39, 3]], zones: [{ id: 'p', r: [81, 27, 29, 26], col: 'blue', label: 'P|P' }] }] },
        pal: ['run', 'stop', 'wait', 'num', 'if', 'else'], ops: ['dist'], scripts: ['start', 'forever'], sol: 'forever{ if:dist<8{ stop:all num:dist } else{ if:dist<30{ run:all,fwd,70 } else{ run:all,fwd,200 } } }',
        check: P => { const nested = l => (l || []).some(b => b.k === 'if' && ((b.e || []).some(x => x.k === 'if') || (b.b || []).some(x => x.k === 'if'))); return nested(P.forever) ? null : "Falta frenar a poc a poc: posa un altre «si» dins del «si no» per tenir tres casos (lluny, a prop i molt a prop).|Falta frenar poco a poco: pon otro «si» dentro del «si no» para tener tres casos (lejos, cerca y muy cerca)."; },
        hint: "Segueix el teu pla: si distància &lt; 8 → atura (i mostra la distància); si no, si distància &lt; 30 → a poc a poc; si no → ràpid.|Sigue tu plan: si distancia &lt; 8 → para (y muestra la distancia); si no, si distancia &lt; 30 → despacio; si no → rápido." },
      { k: 'story', ph: 'tanca', who: 'numi', scene: 'taller', mood: 'happy', title: 'Del simulador al robot de veritat|Del simulador al robot de verdad',
        t: "Enhorabona, enginyers i enginyeres del port! Ara el vostre programa pot anar al <b>Maqueen de veritat</b>: el botó <b>&lt;/&gt;</b> del programa dona el codi per a MakeCode. Al robot real, el sensor pot mesurar 1 o 2 cm diferent i les superfícies toves (roba, escuma) s'empassen el so. Per això sempre cal <b>provar i ajustar</b> a la pista de veritat.|¡Enhorabuena, ingenieros e ingenieras del puerto! Ahora vuestro programa puede ir al <b>Maqueen de verdad</b>: el botón <b>&lt;/&gt;</b> del programa da el código para MakeCode. En el robot real, el sensor puede medir 1 o 2 cm diferente y las superficies blandas (ropa, espuma) se tragan el sonido. Por eso siempre hay que <b>probar y ajustar</b> en la pista de verdad." },
      { k: 'quiz', ph: 'tanca', q: "En un programa de tres casos, quina pregunta ha d'anar primer?|En un programa de tres casos, ¿qué pregunta tiene que ir primero?",
        opts: ["La del cas més urgent: «distància &lt; 8?» (molt a prop)|La del caso más urgente: «¿distancia &lt; 8?» (muy cerca)", "La de «distància &lt; 30?»|La de «¿distancia &lt; 30?»", "És igual: l'ordre no importa|Da igual: el orden no importa"], a: 0,
        ex: "El robot es queda amb la primera pregunta que diu sí. Si a dalt hi ha «&lt; 30», a 5 cm també diu sí i mai s'atura.|El robot se queda con la primera pregunta que dice sí. Si arriba está «&lt; 30», a 5 cm también dice sí y nunca se para." },
      { k: 'quiz', ph: 'tanca', q: "Per què provem el programa a <b>3 pistes diferents</b>?|¿Por qué probamos el programa en <b>3 pistas diferentes</b>?",
        opts: ["Per assegurar-nos que el robot decideix amb el sensor i funciona sigui on sigui la paret|Para asegurarnos de que el robot decide con el sensor y funciona esté donde esté la pared", 'Perquè el simulador va més ràpid|Porque el simulador va más rápido', 'Per tenir més punts|Para tener más puntos'], a: 0 },
      { k: 'feel', ph: 'tanca' }
    ] }
] };
